<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class SiteAccessService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly PermissionRepository $permissions) {}
    public function restricted(?string $user=null): bool {return $this->permissions->userHasPermission($user??$this->actor(),'site_scope.restricted');}
    public function allowed(mixed $site): bool {$id=$this->number($site);return !$this->restricted()||(bool)$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:actor AND site_id=:site',['company'=>$this->company(),'actor'=>$this->actor(),'site'=>$id]);}
    public function requireSite(mixed $site): array {$record=$this->site($site);if(!$this->allowed($record['site_id']))throw HttpException::notFound('Assigned site not found.');return $record;}
    public function sites(): array {
        return $this->db->fetchAll('SELECT s.site_id,s.site_name,s.client_id FROM sites s WHERE s.company_id=:company AND s.deleted_at IS NULL'.($this->restricted()?' AND EXISTS(SELECT 1 FROM user_site_grants g WHERE g.company_id=s.company_id AND g.site_id=s.site_id AND g.user_id=:actor)':'').' ORDER BY s.site_name LIMIT 500',$this->restricted()?['company'=>$this->company(),'actor'=>$this->actor()]:['company'=>$this->company()]);
    }
    public function grants(): array {return $this->db->fetchAll('SELECT grant_id,user_id,site_id,granted_at,granted_by_user_id FROM user_site_grants WHERE company_id=:company ORDER BY user_id,site_id LIMIT 1000',['company'=>$this->company()]);}
    public function grant(array $input): array {return $this->atomic(function()use($input){$this->fields($input,['user_id','site_id']);$user=$this->row('users','user_id',$input['user_id']??null);$site=$this->site($input['site_id']??null);if($user['status']!=='ACTIVE')throw HttpException::unprocessable('Choose an active account.');$keys=['company'=>$this->company(),'user'=>$user['user_id'],'site'=>$site['site_id']];$old=$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:user AND site_id=:site',$keys);if($old)return ['id'=>(string)$old['grant_id']];$this->db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(:company,:user,:site,:actor,:now)',$keys+['actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('user_site_grant');});}
    public function revoke(string $id): array {return $this->atomic(function()use($id){$this->row('user_site_grants','grant_id',$id);$this->db->execute('DELETE FROM user_site_grants WHERE company_id=:company AND grant_id=:id',['company'=>$this->company(),'id'=>$id]);$this->audit->record('user_site_grant','revoked',$id);return ['revoked'=>true];});}
    public function restrictRole(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['role_id','restricted']);$role=$this->row('roles','role_id',$input['role_id']??null);if(!is_bool($input['restricted']??null))throw HttpException::unprocessable('Use a boolean restriction setting.');if($input['restricted']&&$this->db->fetch('SELECT role_id FROM user_roles WHERE company_id=:company AND role_id=:role AND user_id=:actor',['company'=>$this->company(),'role'=>$role['role_id'],'actor'=>$this->actor()]))throw HttpException::conflict('Use a separate supervisor/contractor role; do not restrict your own administrator role.');
        $permission=$this->db->fetch("SELECT permission_id FROM permissions WHERE company_id=:company AND permission_code='site_scope.restricted' AND status='ACTIVE'",['company'=>$this->company()])??throw HttpException::unprocessable('Seed the site-scope marker permission first.');$keys=['company'=>$this->company(),'role'=>$role['role_id'],'permission'=>$permission['permission_id']];$this->db->execute('DELETE FROM role_permissions WHERE company_id=:company AND role_id=:role AND permission_id=:permission',$keys);if($input['restricted'])$this->db->execute('INSERT INTO role_permissions(company_id,role_id,permission_id) VALUES(:company,:role,:permission)',$keys);$this->audit->record('site_scope_role',$input['restricted']?'restricted':'unrestricted',(string)$role['role_id']);return ['restricted'=>$input['restricted']];
    });}
    public function workspace(array $input): array {
        $this->fields($input,['site_id']);$site=$this->requireSite($input['site_id']??null);$keys=['company'=>$this->company(),'site'=>$site['site_id']];return ['site'=>$site,'instructions'=>$this->db->fetch('SELECT revision,title,instructions,emergency_contacts,published_at FROM site_instruction_versions WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 1',$keys),'open_incidents'=>$this->db->fetchAll("SELECT incident_id,incident_number,severity,status,occurred_at FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND status IN ('OPEN','INVESTIGATING') ORDER BY incident_id DESC LIMIT 100",$keys),'faults'=>$this->db->fetchAll("SELECT ticket_id,title,priority,state,updated_at FROM maintenance_tickets WHERE company_id=:company AND site_id=:site AND state NOT IN ('VERIFIED','CANCELLED') ORDER BY ticket_id DESC LIMIT 100",$keys)];
    }
}
